@pytest.fixture(autouse=True)
def engines() -> None:
    """Routes are read from the app, not a database: this file needs no container."""


def test_q02_the_app_serves_exactly_the_generated_routes() -> None:
    assert served(app()) == (list(ROUTES), list(UNAUTHENTICATED))


@pytest.mark.parametrize(("method", "path", "action"), ROUTES)
def test_adr027_the_route_declares_one_action_a_response_model_and_authentication(
    method: str, path: str, action: str
) -> None:
    assert route_problems(app(), method, path, action) == []


def test_p45_only_the_public_route_list_answers_without_a_token() -> None:
    assert public_problems(app(), UNAUTHENTICATED) == []


def test_adr027_every_documented_operation_is_a_generated_route() -> None:
    assert openapi_problems(app(), ROUTES) == []
